const headers = $input.first().json.headers || {};
const expectedToken = $('⚙️ Configuración').item.json.EQUIPZILLA_TOKEN;
const providedToken = headers['x-equipzilla-token'] || headers['X-Equipzilla-Token'];
if (expectedToken && expectedToken !== 'PON_AQUI_TU_EQUIPZILLA_TOKEN' && providedToken !== expectedToken) {
  throw new Error('Auth header X-Equipzilla-Token inválido o ausente');
}

const body = $input.first().json.body || $input.first().json;
const missing = [];
if (!body.deal_id) missing.push('deal_id');
if (!body.machine || !body.machine.category) missing.push('machine.category');
if (!body.dates || !body.dates.start) missing.push('dates.start');
if (!body.location || body.location.lat === undefined) missing.push('location.lat');
if (!body.location || body.location.lng === undefined) missing.push('location.lng');

if (missing.length) {
  return [{ json: { ok: false, error: 'incomplete_payload', missing, raw: body } }];
}

return [{ json: { ok: true, payload: body } }];

const p = $json.payload;
const marginPct = $('⚙️ Configuración').item.json.BUDGET_MARGIN_PCT || 15;
const nowIso = new Date().toISOString();
const trackingRoot = `TRK-${p.deal_id}-${Date.now()}`;

const specs = p.machine.specifications || {};
const specBits = [];
if (specs.tipo_motor) specBits.push(specs.tipo_motor);
if (specs.altura_trabajo_m) specBits.push(`${specs.altura_trabajo_m} m altura de trabajo`);
if (specs.alcance_horizontal_m) specBits.push(`${specs.alcance_horizontal_m} m alcance horizontal`);
if (specs.peso_kg) specBits.push(`${specs.peso_kg} kg`);
if (specs.potencia_kw) specBits.push(`${specs.potencia_kw} kW`);
const subcat = (p.machine.subcategory || p.machine.category || 'maquina').replace(/_/g, ' ');
const desc = `${subcat.charAt(0).toUpperCase() + subcat.slice(1)}${specBits.length ? ' ' + specBits.join(', ') : ''}`;

const constraints = [];
if (p.notes) {
  const n = String(p.notes);
  if (/zbe|baja[s]?\s*emis/i.test(n)) constraints.push('Acceso restringido por ZBE / bajas emisiones');
  if (/altura\s*libre/i.test(n)) constraints.push('Restricción de altura libre');
  if (/peso\s*m[áa]ximo/i.test(n)) constraints.push('Restricción de peso máximo');
  if (/acceso\s*restring/i.test(n)) constraints.push('Acceso restringido');
}

const targetEur = (p.budget && p.budget.daily_rate_target_eur) || null;
const maxEur = targetEur ? Math.round(targetEur * (1 + marginPct / 100)) : null;

const oferta = {
  tracking_root_id: trackingRoot,
  deal_id_internal: p.deal_id,
  original_supplier_id: p.original_supplier_id || null,
  machine: {
    category: p.machine.category,
    subcategory: p.machine.subcategory || null,
    specifications: specs,
    descripcion_legible: desc
  },
  dates: {
    start: p.dates.start,
    end: p.dates.end || null,
    duration_days: p.dates.duration_days || null,
    urgency: p.urgency || 'normal'
  },
  location: {
    city: (p.location && p.location.city) || null,
    postal_code: (p.location && p.location.postal_code) || null,
    zone_label: (p.location && (p.location.zone_label || p.location.city)) || null,
    lat: p.location.lat,
    lng: p.location.lng
  },
  constraints,
  budget_range: { daily_rate_target_eur: targetEur, daily_rate_max_eur: maxEur },
  generated_at: nowIso
};

return [{ json: { oferta_anonimizada: oferta, raw_payload: p, deal_id: p.deal_id } }];

const p = $json.raw_payload;
const oferta = $json.oferta_anonimizada;
const serialized = JSON.stringify(oferta).toLowerCase();
const digitsOnly = serialized.replace(/[^0-9]/g, '');

const forbidden = [];
const pushIf = (label, value) => {
  if (!value) return;
  const v = String(value).toLowerCase().trim();
  if (v.length < 3) return;
  forbidden.push({ label, value: v });
};

pushIf('client.company_name', p.client && p.client.company_name);
pushIf('client.contact_name', p.client && p.client.contact_name);
pushIf('client.email', p.client && p.client.email);
pushIf('client.id', p.client && p.client.id);
if (p.client && p.client.nif) pushIf('client.nif', p.client.nif);
if (p.location && p.location.address) pushIf('location.address', p.location.address);

const hits = [];
for (const f of forbidden) {
  if (serialized.includes(f.value)) hits.push(f);
}
if (p.client && p.client.phone) {
  const d = String(p.client.phone).replace(/[^0-9]/g, '');
  if (d.length >= 6 && digitsOnly.includes(d)) hits.push({ label: 'client.phone', value: d });
}

if (hits.length) {
  return [{ json: { privacy_ok: false, leaks: hits, deal_id: p.deal_id, oferta_anonimizada: oferta, raw_payload: p } }];
}
return [{ json: { privacy_ok: true, oferta_anonimizada: oferta, raw_payload: p, deal_id: p.deal_id } }];

