  raw_payload: src.raw_payload,
  deal_id: src.deal_id,
  tier12_results: items,
  tier12_count: items.length
} }];

const places = ($json.results || []).slice(0, $('⚙️ Configuración').item.json.TIER3_MAX_RESULTS || 10);
const pool = $('Agrupar Tier 1+2').first().json;
const existingNames = new Set((pool.tier12_results || []).map(r => (r.nombre_comercial || '').toLowerCase().trim()));

const tier3 = places
  .filter(p => p.business_status !== 'CLOSED_PERMANENTLY')
  .filter(p => !existingNames.has((p.name || '').toLowerCase().trim()))
  .map(p => ({
    place_id: p.place_id,
    nombre_comercial: p.name,
    ciudad: ((p.formatted_address || '').split(',').slice(-2, -1)[0] || pool.oferta_anonimizada.location.city || '').trim(),
    lat: p.geometry && p.geometry.location && p.geometry.location.lat,
    lng: p.geometry && p.geometry.location && p.geometry.location.lng,
    rating: p.rating || null,
    formatted_address: p.formatted_address,
    tier: 'TIER_3',
    origen: 'cold_enrichment'
  }));

return tier3.map(item => ({ json: { ...item, _pool: pool } }));

const items = $input.all();
const pool = $('Agrupar Tier 1+2').first().json;

const enriched = items
  .map(it => {
    const r = (it.json && it.json.result) || {};
    const baseIdx = it.json && it.json.place_id;
    const baseFromInput = $('Normalizar Tier 3').all().find(x => x.json.place_id === r.place_id);
    const base = (baseFromInput && baseFromInput.json) || {};
    const phone = r.international_phone_number || r.formatted_phone_number || null;
    return {
      alquilador_id: 'PROSPECT-' + (r.place_id || base.place_id || 'unknown'),
      nombre_comercial: r.name || base.nombre_comercial,
      ciudad: base.ciudad,
      whatsapp: phone ? phone.replace(/[^0-9+]/g, '') : null,
      website: r.website || null,
      email_comercial: null,
      formatted_address: r.formatted_address || base.formatted_address,
      tier: 'TIER_3',
      origen: 'cold_enrichment'
    };
  })
  .filter(r => r.whatsapp || r.email_comercial);

return [{ json: {
  oferta_anonimizada: pool.oferta_anonimizada,
  raw_payload: pool.raw_payload,
  deal_id: pool.deal_id,
  tier12_results: pool.tier12_results,
  tier3_results_enriched: enriched,
  tier3_enriched_count: enriched.length
} }];

// Marcador de alta. La implementación real Postgres se hace en producción.
// Aquí solo arrastramos el pool con los Tier 3 ya enriquecidos.
return [{ json: $json }];

const src = $json;
const tier12 = src.tier12_results || [];
const tier3 = (src.tier3_results_enriched || []).map(r => ({
  alquilador_id: r.alquilador_id,
  nombre_comercial: r.nombre_comercial,
  email_comercial: r.email_comercial,
  whatsapp: r.whatsapp,
  ciudad: r.ciudad,
  tier: 'TIER_3',
  origen: 'cold_enrichment'
}));

const seen = new Set();
const pool = [];
for (const a of [...tier12, ...tier3]) {
  const key = (a.alquilador_id || '') + '|' + (a.whatsapp || '') + '|' + (a.email_comercial || '');
  if (seen.has(key)) continue;
  seen.add(key);
  if (!a.whatsapp && !a.email_comercial) continue;
  pool.push(a);
}

return pool.map(a => ({ json: {
  alquilador: a,
  oferta_anonimizada: src.oferta_anonimizada,
  deal_id: src.deal_id,
  raw_payload: src.raw_payload
} }));

const text = (($json.content && $json.content[0] && $json.content[0].text) || '').trim();
let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  return [{ json: { validacion_privacidad: 'bloqueado', razon_bloqueo: 'parse_error', raw: text, parse_error: String(e) } }];
}
const ctx = $('Split por alquilador').item.json;
if (!parsed.tracking_id) {
  parsed.tracking_id = (ctx.oferta_anonimizada.tracking_root_id || 'TRK') + '-' + (ctx.alquilador.alquilador_id || 'unk');
}
return [{ json: {
  ...parsed,
  alquilador: ctx.alquilador,
  oferta_anonimizada: ctx.oferta_anonimizada,
  deal_id: ctx.deal_id,
  raw_payload: ctx.raw_payload
} }];

