// En producción este nodo escribe en la tabla outreach_log (Postgres).
// Aquí lo dejamos como traza estructurada para no bloquear el flujo si la BBDD no está conectada.
const src = $('Parsear respuesta Claude').item.json;
const row = {
  tracking_id: src.tracking_id,
  deal_id: src.deal_id,
  alquilador_id: src.alquilador && src.alquilador.alquilador_id,
  tier: src.tier_aplicado,
  canal_enviado: 'whatsapp_y_email',
  timestamp_envio: new Date().toISOString(),
  estado_final: 'sin_respuesta',
  filtracion_detectada: false
};
console.log('[outreach_log]', JSON.stringify(row));
return [{ json: { logged: true, ...row } }];

const body = $input.first().json.body || $input.first().json;
let canal = 'unknown', text = '', sender = null, trackingId = null, subject = null;

// WhatsApp Business webhook (Meta)
if (body && body.entry && body.entry[0] && body.entry[0].changes) {
  canal = 'whatsapp';
  const change = body.entry[0].changes[0];
  const msg = change && change.value && change.value.messages && change.value.messages[0];
  if (msg) {
    text = (msg.text && msg.text.body) || msg.button?.text || '';
    sender = msg.from;
  }
}
// Brevo inbound webhook
else if (body && (body.From || body.from || body['email'])) {
  canal = 'email';
  text = body.RawText || body.Text || body.text || body.body || '';
  sender = body.From || body.from || body.email;
  subject = body.Subject || body.subject || null;
  // Tracking via header X-Equipzilla-Tracking si está
  const headers = body.RawHeaders || body.headers || {};
  trackingId = headers['X-Equipzilla-Tracking'] || headers['x-equipzilla-tracking'] || null;
}
// Fallback: payload genérico
else {
  canal = body.canal || 'unknown';
  text = body.respuesta || body.text || '';
  sender = body.from || body.sender || null;
  trackingId = body.tracking_id || null;
}

// Buscar [ref:TRK-...] en el texto si no tenemos tracking_id
if (!trackingId && text) {
  const m = String(text).match(/\[ref:([A-Za-z0-9_\-]+)\]/);
  if (m) trackingId = m[1];
}

return [{ json: {
  canal,
  tracking_id: trackingId,
  alquilador_id: null,
  sender,
  subject,
  respuesta: text,
  received_at: new Date().toISOString(),
  raw: body
} }];

const text = (($json.content && $json.content[0] && $json.content[0].text) || '').trim();
let parsed;
try {
  const clean = text.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { categoria: 'ruido', confianza: 0, requiere_humano: true, razon_humano: 'parse_error' };
}
const ctx = $('Correlacionar tracking').item.json;
return [{ json: { ...parsed, ...ctx } }];

// Comprueba si la oferta entra en margen y si nadie ha reservado ya el deal.
const src = $json;
const dealId = src.tracking_id ? src.tracking_id.split('-').slice(1, 5).join('-') : null;
const staticData = $getWorkflowStaticData('global');
const key = `reserva:${dealId}`;
const now = Date.now();
const fifoMin = $('⚙️ Configuración').item.json.FIFO_RESERVATION_MINUTES || 30;
const windowMs = fifoMin * 60 * 1000;

const tarifa = (src.datos_extraidos && src.datos_extraidos.tarifa_dia_eur) || null;
const targetMax = (src.budget_max_eur) || null; // populated externally if available
const inMargin = tarifa == null || targetMax == null || tarifa <= targetMax;
const requiereHumano = !!src.requiere_humano || !inMargin;

const existing = staticData[key];
const alreadyReserved = existing && (now - existing.reserved_at) < windowMs;

let outcome;
if (alreadyReserved) {
  outcome = 'override_candidate';
} else if (requiereHumano) {
  outcome = 'human_review';
} else {
  staticData[key] = { reserved_at: now, tracking_id: src.tracking_id, tarifa, alquilador_id: src.alquilador_id };
  outcome = 'reserved';
}

return [{ json: { ...src, outcome, deal_id: dealId, reserved_state: staticData[key] || null } }];

