// En producción este nodo recorre outreach_log para el deal y envía mensaje cordial
// a quienes no han ganado. Aquí dejamos la traza estructurada.
const src = $json;
const payload = {
  deal_id: src.deal_id,
  alquilador_ganador: src.alquilador_id,
  mensaje: 'Gracias por tu tiempo. Esta operación ya tiene cobertura asignada. Te contactaremos en próximas solicitudes que encajen con tu flota.\n\nEquipo Equipzilla',
  ts: new Date().toISOString()
};
console.log('[cierre_cordial_broadcast]', JSON.stringify(payload));
return [{ json: payload }];

// En producción: UPDATE alquiladores SET opt_out_comercial=true WHERE id=...
const src = $json;
console.log('[opt_out]', JSON.stringify({ tracking_id: src.tracking_id, sender: src.sender, ts: src.received_at }));
return [{ json: { opt_out_recorded: true, tracking_id: src.tracking_id, sender: src.sender } }];

// En producción: SELECT deal_id FROM outreach_log GROUP BY deal_id HAVING
//   MIN(timestamp_envio) < NOW() - INTERVAL '4 hours' AND
//   bool_or(estado_final='ganador') IS DISTINCT FROM true AND
//   bool_or(escalated) IS DISTINCT FROM true;
// Aquí lo dejamos como traza estructurada con datos del staticData del workflow.
const staticData = $getWorkflowStaticData('global');
const hours = $('⚙️ Configuración').item ? $('⚙️ Configuración').item.json.WATCHDOG_TIMEOUT_HOURS : 4;
const now = Date.now();
const windowMs = hours * 60 * 60 * 1000;
const escalated = [];
for (const [k, v] of Object.entries(staticData)) {
  if (!k.startsWith('reserva:')) continue;
  if (v && v.reserved_at && (now - v.reserved_at) > windowMs && !v.closed && !v.escalated) {
    v.escalated = true;
    escalated.push({ deal_id: k.split(':')[1], state: v });
  }
}
return escalated.length ? escalated.map(e => ({ json: e })) : [{ json: { _empty: true } }];

